#!/bin/sh
set -eu
if [ "$#" -ne 1 ]; then
  printf '%s\n' 'Usage: sh Tools/flash.sh /dev/cu.usbserial-PORT' >&2
  exit 2
fi
bridge_port=$1
cd "$(dirname "$0")/../firmware"
# Source the file generated by espup before running this script.
bridge_build_log=$(mktemp)
trap 'rm -f "$bridge_build_log"' EXIT HUP INT TERM
cargo build --release --locked --message-format=json-render-diagnostics > "$bridge_build_log"
bridge_bootloader=$(python3 - "$bridge_build_log" <<'PY'
import json
import sys
from pathlib import Path
for line in Path(sys.argv[1]).read_text().splitlines():
    item = json.loads(line)
    if item.get('reason') == 'build-script-executed' and 'esp-idf-sys' in item.get('package_id', ''):
        path = Path(item['out_dir']) / 'build/bootloader/bootloader.bin'
        if path.is_file():
            print(path)
            break
else:
    raise SystemExit('ESP-IDF bootloader not found in Cargo build output.')
PY
)
rm -f "$bridge_build_log"
trap - EXIT HUP INT TERM
exec espflash flash --chip esp32 --port "$bridge_port" --baud 460800 --flash-size 4mb \
  --bootloader "$bridge_bootloader" --partition-table partitions.csv \
  --non-interactive --monitor target/xtensa-esp32-espidf/release/nintendo-bridge
